META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–3: ದೈವೀ ಸಂಪತ್ತಿನ ಇಪ್ಪತ್ತಾರು ಗುಣಗಳು; 4–6: ಆಸುರೀ ಸಂಪತ್ತು, ಯಾವುದು ಮುಕ್ತಿ ಕೊಡುತ್ತದೆ ಮತ್ತು ಯಾವುದು ಬಂಧಿಸುತ್ತದೆ; 7–18: ಆಸುರೀ ಸ್ವಭಾವದವರು ಹೇಗೆ ಯೋಚಿಸುತ್ತಾರೆ, ಹೇಗೆ ಬದುಕುತ್ತಾರೆ; 19–20: ಅವರು ಎಲ್ಲಿಗೆ ತಲುಪುತ್ತಾರೆ; 21–24: ನರಕದ ಮೂರು ದ್ವಾರಗಳು, ಮತ್ತು ಶಾಸ್ತ್ರವೇ ಮಾರ್ಗದರ್ಶಿ.',
)
T = {
2: 'ಅಹಿಂಸೆ, ಸತ್ಯ, ಕೋಪವಿಲ್ಲದಿರುವಿಕೆ, ತ್ಯಾಗ, ಶಾಂತಿ, ಚಾಡಿ ಹೇಳದಿರುವಿಕೆ, ಜೀವಿಗಳ ಮೇಲೆ ದಯೆ, ಲೋಭವಿಲ್ಲದಿರುವಿಕೆ, ಮೃದುತ್ವ, ಲಜ್ಜೆ (ತಪ್ಪು ಮಾಡುವಲ್ಲಿ), ಚಂಚಲತೆಯಿಲ್ಲದಿರುವಿಕೆ,',
3: 'ತೇಜಸ್ಸು, ಕ್ಷಮೆ, ಧೈರ್ಯ, ಶುಚಿತ್ವ, ದ್ರೋಹ ಮಾಡದಿರುವಿಕೆ, ಅತಿ ಅಭಿಮಾನವಿಲ್ಲದಿರುವಿಕೆ: ಹೇ ಭಾರತ, ದೈವೀ ಸಂಪತ್ತಿನೊಂದಿಗೆ ಹುಟ್ಟಿದವನಿಗೆ ಇವು ಇರುತ್ತವೆ.',
4: 'ಹೇ ಪಾರ್ಥ, ದಂಭ, ದರ್ಪ, ಅಭಿಮಾನ, ಕೋಪ, ಕಠೋರತೆ ಮತ್ತು ಅಜ್ಞಾನ: ಇವು ಆಸುರೀ ಸಂಪತ್ತಿನೊಂದಿಗೆ ಹುಟ್ಟಿದವನಿಗೆ ಇರುತ್ತವೆ.',
5: 'ದೈವೀ ಸಂಪತ್ತು ಮುಕ್ತಿಗೆ, ಆಸುರೀ ಸಂಪತ್ತು ಬಂಧನಕ್ಕೆ ಒಯ್ಯುತ್ತವೆ. ಹೇ ಪಾಂಡವ, ದುಃಖಿಸಬೇಡ; ನೀನು ದೈವೀ ಸಂಪತ್ತಿನೊಂದಿಗೆ ಹುಟ್ಟಿದ್ದೀಯ.',
6: 'ಹೇ ಪಾರ್ಥ, ಈ ಲೋಕದಲ್ಲಿ ಎರಡು ಬಗೆಯ ಜೀವಿಗಳಿವೆ: ದೈವೀ ಸ್ವಭಾವದವು ಮತ್ತು ಆಸುರೀ ಸ್ವಭಾವದವು. ದೈವೀ ಸ್ವಭಾವವನ್ನು ವಿಸ್ತಾರವಾಗಿ ಹೇಳಿದ್ದೇನೆ; ಈಗ ಆಸುರೀ ಸ್ವಭಾವದ ಬಗ್ಗೆ ನನ್ನಿಂದ ಕೇಳು.',
7: 'ಆಸುರೀ ಸ್ವಭಾವದವರಿಗೆ ಏನು ಮಾಡಬೇಕು, ಏನು ಮಾಡಬಾರದು ಎಂದು ತಿಳಿಯದು. ಅವರಲ್ಲಿ ಶುಚಿತ್ವವಾಗಲಿ, ಸದಾಚಾರವಾಗಲಿ, ಸತ್ಯವಾಗಲಿ ಇರುವುದಿಲ್ಲ.',
8: 'ಜಗತ್ತು ಸತ್ಯವಿಲ್ಲದ್ದು, ಆಧಾರವಿಲ್ಲದ್ದು, ಈಶ್ವರನಿಲ್ಲದ್ದು, ಕೇವಲ ಕಾಮದಿಂದ ಒಂದಕ್ಕೊಂದು ಸೇರಿ ಹುಟ್ಟಿದ್ದು, ಬೇರೇನಿದೆ? ಎಂದು ಅವರು ಹೇಳುತ್ತಾರೆ.',
9: 'ಈ ದೃಷ್ಟಿಯನ್ನು ಹಿಡಿದು, ಆತ್ಮವನ್ನು ಕಳೆದುಕೊಂಡು, ಅಲ್ಪಬುದ್ಧಿಗಳಾಗಿ, ಕ್ರೂರ ಕರ್ಮ ಮಾಡುವವರು ಜಗತ್ತಿನ ನಾಶಕ್ಕಾಗಿ ಶತ್ರುಗಳಾಗಿ ಹುಟ್ಟುತ್ತಾರೆ.',
10: 'ತೀರದ ಕಾಮನೆಗಳನ್ನು ಆಶ್ರಯಿಸಿ, ದಂಭ, ಅಭಿಮಾನ ಮತ್ತು ಮದದಿಂದ ತುಂಬಿ, ಮೋಹದಿಂದ ಕೆಟ್ಟ ಆಲೋಚನೆಗಳನ್ನು ಹಿಡಿದು, ಅಪವಿತ್ರ ವ್ರತಗಳೊಂದಿಗೆ ಅವರು ನಡೆಯುತ್ತಾರೆ.',
11: 'ಸಾಯುವವರೆಗೂ ಕೊನೆಯಿಲ್ಲದ ಚಿಂತೆಗಳನ್ನು ಆಶ್ರಯಿಸಿ, ಕಾಮನೆಗಳ ಅನುಭವವನ್ನೇ ಪರಮ ಗುರಿಯಾಗಿ ಭಾವಿಸಿ, "ಇಷ್ಟೇ ಇರುವುದು" ಎಂದು ನಿಶ್ಚಯಿಸಿಕೊಂಡು,',
12: 'ನೂರಾರು ಆಸೆಯ ಪಾಶಗಳಿಂದ ಬಂಧಿತರಾಗಿ, ಕಾಮಕ್ರೋಧಗಳಿಗೆ ವಶರಾಗಿ, ಭೋಗಕ್ಕಾಗಿ ಅನ್ಯಾಯವಾಗಿ ಹಣ ಕೂಡಿಡಲು ಪ್ರಯತ್ನಿಸುತ್ತಾರೆ.',
13: '"ಇಂದು ನಾನು ಇದನ್ನು ಗಳಿಸಿದೆ, ಈ ಬಯಕೆಯನ್ನು ಈಡೇರಿಸಿಕೊಳ್ಳುತ್ತೇನೆ. ಇದು ನನ್ನದು, ಈ ಹಣವೂ ಮತ್ತೆ ನನ್ನದಾಗುತ್ತದೆ.',
14: 'ಈ ಶತ್ರುವನ್ನು ನಾನು ಕೊಂದೆ, ಇತರರನ್ನೂ ಕೊಲ್ಲುತ್ತೇನೆ. ನಾನು ಈಶ್ವರ, ನಾನು ಭೋಗಿ, ನಾನು ಸಿದ್ಧ, ಬಲಶಾಲಿ ಮತ್ತು ಸುಖಿ.',
15: 'ನಾನು ಶ್ರೀಮಂತ, ದೊಡ್ಡ ಕುಲದಲ್ಲಿ ಹುಟ್ಟಿದವನು; ನನ್ನಂಥವರು ಬೇರೆ ಯಾರಿದ್ದಾರೆ? ಯಜ್ಞ ಮಾಡುತ್ತೇನೆ, ದಾನ ಮಾಡುತ್ತೇನೆ, ಆನಂದಿಸುತ್ತೇನೆ", ಹೀಗೆ ಅಜ್ಞಾನದಿಂದ ಮೋಹಗೊಂಡವರು,',
16: 'ಅನೇಕ ಆಲೋಚನೆಗಳಿಂದ ಭ್ರಮಿಸಿ, ಮೋಹದ ಬಲೆಯಲ್ಲಿ ಸಿಕ್ಕಿ, ಕಾಮನೆಗಳ ಅನುಭವದಲ್ಲಿ ಆಸಕ್ತರಾಗಿ, ಅಪವಿತ್ರ ನರಕಕ್ಕೆ ಬೀಳುತ್ತಾರೆ.',
17: 'ತಮ್ಮನ್ನು ತಾವೇ ದೊಡ್ಡವರೆಂದು ಭಾವಿಸಿಕೊಂಡು, ಹಠಮಾರಿಗಳಾಗಿ, ಹಣ, ಮಾನ ಮತ್ತು ಮದದಿಂದ ತುಂಬಿ, ಅವರು ಹೆಸರಿಗೆ ಮಾತ್ರ ಯಜ್ಞಗಳನ್ನು ಮಾಡುತ್ತಾರೆ, ದಂಭದಿಂದ, ವಿಧಿಯಿಲ್ಲದೆ.',
18: 'ಅಹಂಕಾರ, ಬಲ, ದರ್ಪ, ಕಾಮ ಮತ್ತು ಕ್ರೋಧವನ್ನು ಆಶ್ರಯಿಸಿ, ಈ ಅಸೂಯಾಪರರು ತಮ್ಮ ಮತ್ತು ಇತರರ ದೇಹಗಳಲ್ಲಿರುವ ನನ್ನನ್ನು ದ್ವೇಷಿಸುತ್ತಾರೆ.',
19: 'ದ್ವೇಷಿಸುವ, ಕ್ರೂರರಾದ, ನರಾಧಮರಾದ, ಅಶುಭರಾದ ಅವರನ್ನು ನಾನು ಸಂಸಾರದಲ್ಲಿ ಮತ್ತೆ ಮತ್ತೆ ಆಸುರೀ ಯೋನಿಗಳಲ್ಲೇ ಹಾಕುತ್ತೇನೆ.',
20: 'ಹೇ ಕೌಂತೇಯ, ಆಸುರೀ ಯೋನಿಗಳಲ್ಲಿ ಹುಟ್ಟಿ, ಜನ್ಮಜನ್ಮಕ್ಕೂ ಮೋಹಗೊಂಡು, ನನ್ನನ್ನು ಸೇರದೆ ಆ ಮೂಢರು ಅದಕ್ಕಿಂತಲೂ ಕೀಳು ಗತಿಗೆ ಹೋಗುತ್ತಾರೆ.',
22: 'ಹೇ ಕೌಂತೇಯ, ಕತ್ತಲೆಯ ಈ ಮೂರು ದ್ವಾರಗಳಿಂದ ಮುಕ್ತನಾದ ಮನುಷ್ಯ ತನಗೆ ಹಿತವಾದುದನ್ನು ಆಚರಿಸುತ್ತಾನೆ, ಆದ್ದರಿಂದ ಪರಮ ಗತಿಯನ್ನು ಸೇರುತ್ತಾನೆ.',
23: 'ಶಾಸ್ತ್ರವಿಧಿಯನ್ನು ಬಿಟ್ಟು ತನ್ನ ಇಚ್ಛೆಯಂತೆ ನಡೆಯುವವನು ಸಿದ್ಧಿಯನ್ನು ಪಡೆಯುವುದಿಲ್ಲ, ಸುಖವನ್ನು ಪಡೆಯುವುದಿಲ್ಲ, ಪರಮ ಗತಿಯನ್ನೂ ಪಡೆಯುವುದಿಲ್ಲ.',
24: 'ಆದ್ದರಿಂದ ಏನು ಮಾಡಬೇಕು, ಏನು ಮಾಡಬಾರದು ಎಂದು ನಿರ್ಧರಿಸುವಲ್ಲಿ ಶಾಸ್ತ್ರವೇ ನಿನಗೆ ಪ್ರಮಾಣ. ಶಾಸ್ತ್ರವಿಧಿಯಲ್ಲಿ ಹೇಳಿದ್ದನ್ನು ತಿಳಿದು ಇಲ್ಲಿ ಕರ್ಮ ಮಾಡುವುದು ನಿನಗೆ ತಕ್ಕದ್ದು.',
}
